package com.jayaseelan.nexoramart.controller;
import com.jayaseelan.nexoramart.dao.JdbcUserDAO; import com.jayaseelan.nexoramart.model.User; import com.jayaseelan.nexoramart.service.AuthService; import javax.servlet.annotation.WebServlet; import javax.servlet.ServletException; import javax.servlet.http.*; import javax.sql.DataSource; import java.io.IOException;
@WebServlet("/login") public class LoginServlet extends HttpServlet{private AuthService s;public void init(){s=new AuthService(new JdbcUserDAO((DataSource)getServletContext().getAttribute("dataSource")));}protected void doGet(HttpServletRequest r,HttpServletResponse p)throws ServletException,IOException{r.getRequestDispatcher("/WEB-INF/views/login.jsp").forward(r,p);}protected void doPost(HttpServletRequest r,HttpServletResponse p)throws ServletException,IOException{try{User u=s.login(r.getParameter("email"),r.getParameter("password"));if(u==null){r.setAttribute("error","Invalid email or password.");doGet(r,p);return;}HttpSession x=r.getSession(true);r.changeSessionId();x.setMaxInactiveInterval(1800);x.setAttribute("userId",u.getId());x.setAttribute("userName",u.getName());x.setAttribute("userRole",u.getRole());p.sendRedirect(r.getContextPath() + ("ADMIN".equals(u.getRole()) ? "/admin" : "SELLER".equals(u.getRole()) ? "/seller/dashboard" : "/dashboard"));}catch(Exception e){getServletContext().log("Login failed",e);r.setAttribute("error","Unable to login right now.");doGet(r,p);}}}
